                    'متوسط' => BreakdownSeverity::Medium,
                    default => BreakdownSeverity::Minor,
                };

                $repairStatus = match (true) {
                    $workshopStatus === 'توريد قطع' || $workshopStatus === 'متوقف تسعير' || $workshopStatus === 'دعم مالي' => RepairStatus::WaitingParts,
                    $workshopStatus === 'نقل للورشه المركزيه' || $workshopStatus === 'مؤجل' || $amount === 'خارج الورشه' => RepairStatus::External,
                    default => RepairStatus::InWorkshop,
                };

                $category = $this->inferCategory($fault);
                $estimatedCost = is_numeric($amount) ? (float) $amount : 0.0;
                $costNote = is_string($amount) ? $amount : null;

