                    'equipment_name' => $name,
                    'brand' => $brand,
                    'workshop_name' => $workshop,
                    'category' => $category,
                    'severity' => $severity,
                    'breakdown_date' => $date,
                    'workshop_entry_date' => $date,
                    'expected_repair_date' => $repairDate,
                    'fault_description' => $fault,
                    'repair_status' => $repairStatus,
                    'workshop_status' => $workshopStatus,
                    'spare_parts_delay' => $workshopStatus === 'توريد قطع' || $workshopStatus === 'متوقف تسعير',
                    'estimated_cost' => $estimatedCost,
                    'cost_note' => $costNote,
                    'notes' => $notes,
                ]);
            }
        });

        DashboardService::clearCache();
    }

    protected function inferCategory(string $fault): BreakdownCategory
    {
        if (str_contains($fault, 'حادث')) {
            return BreakdownCategory::Accident;
        }

        if (
            str_contains($fault, 'هيدروليك')
            || str_contains($fault, 'بستم')
            || str_contains($fault, 'بساتم')
            || str_contains($fault, 'طلمب')
            || str_contains($fault, 'بلف الرفع')
        ) {
            return BreakdownCategory::Hydraulic;
        }

        if (
            str_contains($fault, 'كهرباء')
            || str_contains($fault, 'كمبيوتر')
            || str_contains($fault, 'دينمو')
            || str_contains($fault, 'دينامو')
            || str_contains($fault, 'ظفير')
            || str_contains($fault, 'سلف')
            || str_contains($fault, 'كنترول')
            || stripos($fault, 'rpm') !== false
        ) {
            return BreakdownCategory::Electrical;
        }

        if (str_contains($fault, 'إطار') || str_contains($fault, 'اطار') || str_contains($fault, 'كفر')) {
            return BreakdownCategory::Tires;
        }

        return BreakdownCategory::Mechanical;
    }
